public int kind() {
        return switch (BuiltInRegistries.ENTITY_TYPE.getKey(getType()).getPath()) { case "frostilyte_soldier" -> 0; case "frostilyte_cryomancer" -> 1; case "icidrone" -> 2; default -> 3; };
